    private RegistryRemapper() {
    }

    static int[] expand(int[][] ranges, int[][] overrides, int size, int fallback) {
        int[] map = new int[size];
        java.util.Arrays.fill(map, fallback);
        for (int[] range : ranges) {
            int start = range[0];
            int end = range[1];
            int delta = range[2];
            for (int i = start; i <= end && i < size; i++) {
                map[i] = i + delta;
            }
        }
        for (int[] override : overrides) {
            if (override[0] >= 0 && override[0] < size) {
                map[override[0]] = override[1];
            }
        }
        return map;
    }

    private static Map<String, String> buildSoundNameMap() {
        return buildSoundNameMap(SOUND_NAME_FALLBACKS);
    }

    private static Map<String, String> buildSoundNameMap(String[][] table) {
        Map<String, String> map = new java.util.HashMap<>();
        for (String[] pair : table) {
            map.put(pair[0], pair[1]);
        }
        return Map.copyOf(map);
    }

