    /**
     * 765→764の対応表（区間＋上書き）を反転して764→765の表を作る。
     * 第1パスで区間由来の対応を、第2パスで上書き由来の対応を入れる
     * （先に入った方を優先し、後からは上書きしない）。最後に
     * {@code corrections}（764 id → 765 id）があれば上書きする。
     * 埋まらなかった番号は {@code fallback}（765側の代替先）で埋める。
     */
    static int[] invert(int[][] ranges, int[][] overrides,
            int fromSize, int toSize, int fallback, int[][] corrections) {
        int[] inverse = new int[toSize];
        java.util.Arrays.fill(inverse, -1);
        for (int[] range : ranges) {
            for (int x = range[0]; x <= range[1] && x < fromSize; x++) {
                int y = x + range[2];
                if (y >= 0 && y < toSize && inverse[y] < 0) {
                    inverse[y] = x;
                }
            }
        }
        for (int[] override : overrides) {
            int x = override[0];
            int y = override[1];
            if (x >= 0 && x < fromSize && y >= 0 && y < toSize && inverse[y] < 0) {
                inverse[y] = x;
            }
        }
        if (corrections != null) {
            for (int[] correction : corrections) {
                if (correction[0] >= 0 && correction[0] < toSize
                        && correction[1] >= 0 && correction[1] < fromSize) {
                    inverse[correction[0]] = correction[1];
                }
            }
        }
        for (int i = 0; i < toSize; i++) {
            if (inverse[i] < 0) {
                inverse[i] = fallback;
            }
        }
        return inverse;
    }

