    /** 765のブロック状態ID → 763のブロック状態ID。範囲外は石（1）。 */
    public static int mapBlockState(int id765) {
        if (id765 < 0 || id765 > MAX_BLOCK_STATE_765) {
            logUnknownOnce(PROTOCOL_763, "ブロック状態", id765);
            return STONE_BLOCK_STATE_763;
        }
        return BLOCK_STATE_MAP[id765];
    }

    /** 765のアイテムID → 763のアイテムID。範囲外は石（1）。 */
    public static int mapItem(int id765) {
        if (id765 < 0 || id765 > MAX_ITEM_765) {
            logUnknownOnce(PROTOCOL_763, "アイテム", id765);
            return STONE_ITEM_763;
        }
        return ITEM_MAP[id765];
    }

    /**
     * 763のアイテムID → 765のアイテムID（サーバー行きスロット用）。
     * 763にしか無い grass は 765の short_grass へ。範囲外はそのまま返す。
     */
    public static int mapItemReverse(int id763) {
        if (id763 < 0 || id763 >= ITEM_REVERSE_MAP.length) {
            logUnknownOnce(PROTOCOL_763, "アイテム（逆変換）", id763);
            return id763;
        }
        int mapped = ITEM_REVERSE_MAP[id763];
        return mapped < 0 ? id763 : mapped;
    }

