    private static String mapSoundNameComposed(String name, Map<String, String> table) {
        if (name == null) {
            return "minecraft:block.stone.break";
        }
        String bare = name.startsWith("minecraft:") ? name.substring("minecraft:".length()) : name;
        String prefix = name.startsWith("minecraft:") ? "minecraft:" : "";
        String fallback = table.get(bare);
        if (fallback != null) {
            return prefix + fallback;
        }
        return name;
    }

